// n8n Code node (JavaScript)
// Input: items[] where each item.json.text is the full extracted PDF text
// Output: one item per input with parsed fields

function pickFirst(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
}

function getMatch(text, regex, group = 1) {
  const m = regex.exec(text);
  return m && m[group] ? m[group].trim() : null;
}

function normalizeDate(dStr) {
  if (!dStr) return null;

  // Handle PDF-style dates like "2.12.2024" or "02.12.2024" or "2024-12-02"
  const dot = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/; // D.M.YYYY
  const iso = /^(\d{4})-(\d{2})-(\d{2})$/;

  if (dot.test(dStr)) {
    const [, d, m, y] = dot.exec(dStr);
    const dd = d.padStart(2, '0');
    const mm = m.padStart(2, '0');
    return `${y}-${mm}-${dd}`;
  }
  if (iso.test(dStr)) return dStr;

  // Try to parse with Date for other locales (e.g., "Dec 2, 2024")
  const parsed = new Date(dStr);
  if (!isNaN(parsed)) {
    const y = parsed.getFullYear();
    const m = String(parsed.getMonth() + 1).padStart(2, '0');
    const d = String(parsed.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  return null;
}

function parseEuroToNumber(s) {
  if (s == null) return null;
  // Accept "1.234,56 EUR" or "0,00" or "1234.56"
  let cleaned = String(s).replace(/\s?EUR/i, '').trim();
  // If comma is decimal separator, swap
  if (/,\d{1,2}$/.test(cleaned)) {
    cleaned = cleaned.replace(/\./g, '').replace(',', '.');
  }
  const num = Number(cleaned);
  return isNaN(num) ? null : num;
}

function daysBetweenISO(fromISO, toISO) {
  if (!fromISO || !toISO) return null;
  const ms = (new Date(toISO).setHours(0,0,0,0)) - (new Date(fromISO).setHours(0,0,0,0));
  return Math.round(ms / (1000 * 60 * 60 * 24));
}

function computeDaysLeft(dueISO, totalDueAmount) {
  if (!dueISO) return totalDueAmount && totalDueAmount > 0 ? null : 0;
  // Use "today" (server time). Adjust if you prefer a fixed timezone.
  const today = new Date();
  const y = today.getFullYear();
  const m = String(today.getMonth() + 1).padStart(2, '0');
  const d = String(today.getDate()).padStart(2, '0');
  const todayISO = `${y}-${m}-${d}`;
  const diff = daysBetweenISO(todayISO, dueISO);
  // If already past due, show negative days left
  return diff;
}

return items.map(item => {
  const text = String(item.json.text || '');

  // --- Core fields (robust regexes for German/English variants) ---
  const invoiceNumber = pickFirst(
    getMatch(text, /Rechnungsnummer\s*([\w-]+)/i),
    getMatch(text, /Invoice\s*Number[:\s]*([\w-]+)/i),
    getMatch(text, /\bInvoice\s*#[:\s]*([\w-]+)/i)
  );

  const dateOfIssueRaw = pickFirst(
    getMatch(text, /Transaktionsdatum\s*([0-9]{1,2}\.[0-9]{1,2}\.[0-9]{4})/i),
    getMatch(text, /Datum des Inkrafttretens\s*([0-9]{1,2}\.[0-9]{1,2}\.[0-9]{4})/i),
    getMatch(text, /Date of Issue[:\s]*([^\n]+)/i),
    getMatch(text, /\bIssue Date[:\s]*([^\n]+)/i)
  );
  const dateOfIssue = normalizeDate(dateOfIssueRaw);

  const dueDateRaw = pickFirst(
    getMatch(text, /Fälligkeitsdatum\s*([0-9]{1,2}\.[0-9]{1,2}\.[0-9]{4})/i),
    getMatch(text, /Due\s*Date[:\s]*([0-9]{1,2}\.[0-9]{1,2}\.[0-9]{4})/i),
    getMatch(text, /Due\s*Date[:\s]*([^\n]+)/i) // fallback
  );
  const dueDate = normalizeDate(dueDateRaw);

  const customer = pickFirst(
    getMatch(text, /Empfänger:in\s*([^\n]+)\n/i),
    getMatch(text, /Customer[:\s]*([^\n]+)/i),
    getMatch(text, /Bill To[:\s]*([^\n]+)/i),
    getMatch(text, /Käufer:in\s*([^\n]+)\n/i)
  );

  const seller = pickFirst(
    getMatch(text, /(LinkedIn Ireland Unlimited Company)/i),
    getMatch(text, /Seller[:\s]*([^\n]+)/i),
    getMatch(text, /Verkäufer[:\s]*([^\n]+)/i),
    getMatch(text, /^([^\n]+?Company[^\n]*)$/im) // generic company line
  );

  const paymentMethod = pickFirst(
    getMatch(text, /Zahlungsmethode\s*([^\n]+)/i),
    getMatch(text, /Payment\s*Method[:\s]*([^\n]+)/i)
  );

  // Monetary fields (German layout present in sample)
  const netPriceRaw = pickFirst(
    getMatch(text, /Zwischensumme\s*:\s*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Netto(?:betrag)?[:\s]*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Subtotal[:\s]*([0-9\.\,]+\s*EUR)/i)
  );
  const netPrice = parseEuroToNumber(netPriceRaw);

  const taxRaw = pickFirst(
    getMatch(text, /USt\.\s*:\s*([0-9\.\,]+(?:\s*EUR|%))/i),
    getMatch(text, /Steuer[:\s]*([0-9\.\,]+(?:\s*EUR|%))/i),
    getMatch(text, /Tax[:\s]*([0-9\.\,]+(?:\s*EUR|%))/i)
  );
  // Represent tax as string (e.g., "0%" or amount). Keep original if percentage.
  const tax = taxRaw ? taxRaw.replace(/\s+/g, ' ').trim() : null;

  const grossValueRaw = pickFirst(
    getMatch(text, /Insgesamt\s*:\s*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Bruttobetrag[:\s]*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Total[:\s]*([0-9\.\,]+\s*EUR)/i)
  );
  const grossValue = parseEuroToNumber(grossValueRaw);

  const totalDueRaw = pickFirst(
    getMatch(text, /Ausstehender Betrag\s*:\s*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Fälliger Betrag[:\s]*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Total Due[:\s]*([0-9\.\,]+\s*EUR)/i),
    getMatch(text, /Balance Due[:\s]*([0-9\.\,]+\s*EUR)/i)
  );
  const totalDue = parseEuroToNumber(totalDueRaw);

  // Days left to pay (if no due date or nothing due, default sensible)
  const daysLeftToPay = computeDaysLeft(dueDate, totalDue);

  // Build final JSON
  const json = {
    invoiceNumber: invoiceNumber,
    dateOfIssue: dateOfIssue,          // ISO (YYYY-MM-DD) when parsed
    dueDate: dueDate,                  // ISO or null
    customer: customer,
    netPrice: netPrice,                // number (EUR)
    grossValue: grossValue,            // number (EUR)
    tax: tax,                          // string like "0%" or "19%"/"5,70 EUR"
    totalDue: totalDue,                // number (EUR)
    paymentMethod: paymentMethod,
    seller: seller,
    daysLeftToPay: daysLeftToPay       // integer (negative if overdue, 0 if none due/missing)
  };

  return { json };
});
